import axios from 'axios'
import store from '@/store'
import router from '@/router'

const axiosInstance = axios.create({
  baseURL: 'http://localhost:8000',
})

axiosInstance.interceptors.request.use(async config => {
    const token = store.state.token || localStorage.getItem('token')  // Check both Vuex and localStorage
    if (token) {
      config.headers.Authorization = `Bearer ${token}`
    } else {
      console.log('No token found in the state')
    }
    return config
  },
  error => {
    return Promise.reject(error)
  })

axiosInstance.interceptors.response.use(
  response => response,
  async error => {
    const originalRequest = error.config
    if (error.response.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true
      await store.dispatch('refreshToken', error.response.data.refreshToken)
      return axiosInstance(originalRequest)
    }
    if (error.response && error.response.status === 401 && store.getters.isAuthenticated) {
      // Only logout if the user was previously authenticated
      await store.dispatch('logout')
      router.push('/login')
    }
    return Promise.reject(error)
  }
)

export default axiosInstance
